), selected_logs AS (
  SELECT l.*
  FROM ethereum.logs l
  JOIN requested r ON l.tx_hash = r.tx_hash
                  AND l.block_number = r.expected_block
  WHERE l.block_time >= TIMESTAMP '2021-06-14 00:00:00'
    AND l.block_time <  TIMESTAMP '2021-06-15 00:00:00'
    AND l.block_number BETWEEN 10000835 AND 15400000
)
SELECT
  r.source_row, r.review_role, r.expected_block, r.expected_swap_log_index,
  concat('0x', to_hex(r.tx_hash)) AS requested_tx_hash,
  r.csv_amount0_in_raw, r.csv_amount0_out_raw,
  r.csv_amount1_in_raw, r.csv_amount1_out_raw,
  l.tx_hash IS NOT NULL AS log_found,
  l.block_number, l.block_time, l.tx_index AS transaction_index,
  l."index" AS log_index,
  concat('0x', to_hex(l.contract_address)) AS contract_address,
  concat('0x', to_hex(l.tx_from)) AS tx_from,
  concat('0x', to_hex(l.tx_to)) AS tx_to,
  concat('0x', to_hex(l.topic0)) AS topic0,
  concat('0x', to_hex(l.topic1)) AS topic1,
  concat('0x', to_hex(l.topic2)) AS topic2,
  concat('0x', to_hex(l.topic3)) AS topic3,
  concat('0x', to_hex(l.data)) AS data_hex,
  COALESCE(l.contract_address = 0x669fbbd3612910ff1394f657900fbb8f335d044d
           AND l."index" = r.expected_swap_log_index, FALSE) AS is_requested_pool_event
FROM requested r
LEFT JOIN selected_logs l ON l.tx_hash = r.tx_hash
                        AND l.block_number = r.expected_block
ORDER BY r.source_row, l."index"
-- LEFT JOIN retains a missing-log indicator if a request has no matching logs.
-- No LIMIT: retain every returned row for coverage review.
